const fs=require('fs'),path=require('path'),zlib=require('zlib');const f=JSON.parse(zlib.gunzipSync(Buffer.from('','base64')));const base=JSON.parse(zlib.gunzipSync(Buffer.from(require('./assets-0.cjs')+require('./assets-1.cjs')+require('./assets-2.cjs'),'base64')));for(const[n,b]of Object.entries(base)){if(n.startsWith('sequence/')||n.startsWith('fonts/'))f['site/'+n]=b;}for(const[n,b]of Object.entries(f)){const p=path.resolve('source',n);if(!p.startsWith(path.resolve('source')+path.sep))throw Error('Unsafe source path');fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,Buffer.from(b,'base64'));}console.log('Editable source extracted to source/');
